# Generated by build.py from recipe.yml for recipe http-run-a-test-proxy. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--trace-ascii', 'site/origin.txt', 'http://127.0.0.1:8080/', '--proxy', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -x http://127.0.0.1:8081/ http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
